    this.input = { x: 0, y: 0, tiltX: 0, tiltY: 0, tiltOn: false };
    this.ball = this.createBall();
    this.ghostMesh = this.createGhost();
    this.recording = [];
    this.recordAcc = 0;
    this.recordingEnabled = true;
    this.ghost = null;
    this.countdownT = 0;
    this.lastCount = 0;
    this.resuming = false;
    this.bestSplits = null;
    this.splits = [];

    this.builder = {
      active: false,
      map: null,
      level: 0,
      tool: 'plat',
      rot: 0,
      hover: null,
