.mini-btn {
  width: 28px; height: 28px; border-radius: 8px; border: 1px solid rgba(255,255,255,.18);
  background: rgba(8,6,20,.64); display: grid; place-items: center; color: var(--cream);
  backdrop-filter: blur(6px); transition: background .15s, transform .12s;
}
.mini-btn:hover { background: rgba(255,255,255,.16); }
.mini-btn:active { transform: scale(.92); }
.mini-btn svg { width: 14px; height: 14px; }
.create-card {
  appearance: none; border: 1px dashed rgba(255,255,255,.25);
  background: linear-gradient(135deg, rgba(255,106,61,.08), rgba(255,255,255,.025));
  color: var(--cream); border-radius: 21px; min-height: 110px; padding: 18px;
  display: flex; align-items: center; gap: 14px; text-align: left;
  transition: background .2s, border-color .2s, transform .15s;
}
.create-card:hover { border-color: rgba(255,200,100,.55); background: linear-gradient(135deg, rgba(255,106,61,.16), rgba(255,255,255,.05)); transform: translateY(-1px); }
.create-plus {
  width: 46px; height: 46px; border-radius: 14px; flex: none;
  display: grid; place-items: center; font-size: 1.6rem; font-weight: 300;
  background: linear-gradient(180deg, #ff8250, #ff5b35); border: 1px solid rgba(255,255,255,.3);
  box-shadow: 0 4px 0 rgba(160,40,16,.7);
}
.create-card b { display: block; font-family: 'Baloo 2', sans-serif; font-size: 1.1rem; }
.create-card small { color: var(--muted-2); font-size: .7rem; }
.empty-state { padding: 18px 8px 8px; color: var(--muted-2); font-size: .76rem; line-height: 1.5; }

/* ---------------- HUD ---------------- */

.hud { position: absolute; inset: 0; pointer-events: none; }
.hud-top {
  display: flex; justify-content: space-between; align-items: flex-start; gap: 12px;
  padding: calc(14px + var(--safe-t)) calc(14px + var(--safe-r)) 0 calc(14px + var(--safe-l));
}
.timer-cluster {
  background: linear-gradient(180deg, rgba(24, 18, 48, .82), rgba(11, 8, 24, .74));
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 20px; padding: 10px 16px 9px;
  min-width: 194px;
  box-shadow: 0 10px 28px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.1);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
}
.hud-map { font-size: .57rem; font-weight: 800; letter-spacing: .16em; color: var(--muted); text-transform: uppercase; margin-bottom: 1px; }
.timer { font-size: 1.95rem; line-height: 1; font-weight: 700; letter-spacing: .01em; font-variant-numeric: tabular-nums; white-space: nowrap; }
.timer-sub { display: flex; align-items: center; gap: 8px; margin-top: 3px; font-size: .6rem; letter-spacing: .1em; color: var(--muted-2); font-weight: 700; min-height: 16px; }
.ghost-badge {
  background: rgba(76, 230, 216, .14); color: var(--cyan); border: 1px solid rgba(76,230,216,.32);
  border-radius: 999px; padding: 2px 6px; font-size: .52rem; letter-spacing: .1em;
}
.hud-right { display: flex; align-items: center; gap: 8px; }
.cp-pill {
  background: rgba(15,11,30,.68); border: 1px solid rgba(255,255,255,.14);
  border-radius: 999px; padding: 10px 13px; font-size: .64rem; font-weight: 800; letter-spacing: .1em;
  color: var(--muted); backdrop-filter: blur(12px);
}
.cp-pill.active { color: var(--cyan); border-color: rgba(76,230,216,.4); }
.pause-btn { pointer-events: auto; width: 44px; height: 44px; background: rgba(15,11,30,.7); }

.split-toast {
  position: absolute; top: calc(108px + var(--safe-t)); left: 50%; transform: translate(-50%, -10px);
  background: rgba(12,9,26,.86); border: 1px solid rgba(255,255,255,.14); border-radius: 999px;
  padding: 8px 16px; font-size: .75rem; font-weight: 700; letter-spacing: .04em;
  opacity: 0; transition: opacity .25s, transform .25s; pointer-events: none; white-space: nowrap;
  box-shadow: 0 8px 24px rgba(0,0,0,.3);
}
.split-toast.show { opacity: 1; transform: translate(-50%, 0); }
.split-toast .good { color: var(--green); }
.split-toast .bad { color: #ff8a8a; }

.hint-banner {
  position: absolute; left: 50%; bottom: calc(20px + var(--safe-b)); transform: translateX(-50%);
  background: rgba(12,9,26,.62); border: 1px solid rgba(255,255,255,.1); border-radius: 999px;
  padding: 7px 14px; font-size: .66rem; letter-spacing: .05em; color: var(--muted);
  backdrop-filter: blur(10px); pointer-events: none; transition: opacity .5s;
  opacity: 0;
}
body.touch .hint-banner { bottom: calc(162px + var(--safe-b)); }
.hint-banner.show { opacity: 1; }
.desktop-hint {
  position: absolute; bottom: calc(16px + var(--safe-b)); left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 7px; font-size: .65rem; color: rgba(255,255,255,.4);
  letter-spacing: .04em; pointer-events: none;
}

/* ---------------- Touch controls ---------------- */

.mobile-controls { display: none; }
body.touch .mobile-controls { display: block; }
body.touch .desktop-hint { display: none; }
.joystick {
  position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(24px + var(--safe-b));
  width: 132px; height: 132px; pointer-events: auto; touch-action: none;
  display: grid; place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,.055) 0 48%, transparent 49%);
}
.joy-ring {
  position: absolute; inset: 8px; border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.25);
  background: radial-gradient(circle at 36% 30%, rgba(255,255,255,.13), rgba(10,7,24,.28) 65%);
  box-shadow: inset 0 0 24px rgba(255,255,255,.05), 0 8px 24px rgba(0,0,0,.22);
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
}
.joy-ring::before, .joy-ring::after {
  content: ''; position: absolute; background: rgba(255,255,255,.1);
}
.joy-ring::before { left: 50%; top: 16%; bottom: 16%; width: 1px; }
.joy-ring::after { top: 50%; left: 16%; right: 16%; height: 1px; }
.joy-knob {
  position: absolute; width: 58px; height: 58px; border-radius: 50%;
  background:
    radial-gradient(circle at 32% 26%, rgba(255,255,255,.95) 0 8%, transparent 10%),
    radial-gradient(circle at 35% 30%, #ffe8c8, #ff9b62 45%, #d94a5f 100%);
  border: 2px solid rgba(255,255,255,.5);
  box-shadow: 0 7px 18px rgba(0,0,0,.35), inset -4px -6px 10px rgba(100,20,50,.28);
  transform: translate(0, 0);
  will-change: transform;
  z-index: 2;
}
.joy-label {
  position: absolute; bottom: -7px; left: 50%; transform: translateX(-50%);
  font-size: .5rem; letter-spacing: .18em; font-weight: 800; color: rgba(255,255,255,.35);
}
.right-controls {
  position: absolute; right: calc(24px + var(--safe-r)); bottom: calc(26px + var(--safe-b));
  display: flex; flex-direction: column; align-items: center; gap: 12px; pointer-events: auto;
}
.jump-btn {
  width: 92px; height: 92px; border-radius: 50%;
  border: 2px solid rgba(255,255,255,.4);
  background:
    radial-gradient(circle at 34% 25%, rgba(255,255,255,.9) 0 6%, transparent 8%),
    radial-gradient(circle at 40% 30%, #ffb16e, #ff6239 52%, #d43a27 100%);
  color: white; font-family: 'Baloo 2', sans-serif; font-size: 1.15rem; font-weight: 800; letter-spacing: .05em;
  text-shadow: 0 2px 0 rgba(120,30,10,.3);
  box-shadow: 0 7px 0 #a92d1b, 0 14px 26px rgba(0,0,0,.3), inset 0 2px 0 rgba(255,255,255,.3);
  touch-action: none; user-select: none;
  transition: transform .08s, box-shadow .08s;
}
.jump-btn:active, .jump-btn.pressed { transform: translateY(5px) scale(.96); box-shadow: 0 2px 0 #a92d1b, 0 5px 12px rgba(0,0,0,.25); }

/* ---------------- Countdown / flash ---------------- */

.countdown {
  position: absolute; inset: 0; display: grid; place-items: center;
  pointer-events: none; z-index: 6;
}
.countdown span {
  font-family: 'Baloo 2', sans-serif;
  font-size: clamp(6rem, 18vw, 13rem);
  font-weight: 800;
  line-height: 1;
  color: var(--cream);
  text-shadow: 0 8px 0 rgba(0,0,0,.18), 0 0 60px rgba(255, 150, 80, .55), 0 20px 60px rgba(0,0,0,.4);
  animation: countPop .55s cubic-bezier(.2,1.4,.3,1);
}
.countdown.go span { color: var(--yellow); text-shadow: 0 0 80px rgba(255,201,60,.8), 0 8px 0 rgba(0,0,0,.18); }
.flash { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(circle, rgba(255,255,255,.2), rgba(255,70,80,.5)); }
.flash.hit { animation: flashHit .5s ease-out; }
.flash.good { background: radial-gradient(circle, rgba(255,255,255,.2), rgba(76,230,216,.38)); animation: flashHit .5s ease-out; }

/* ---------------- Overlay screens ---------------- */

.overlay-screen {
  pointer-events: auto;
  display: flex; align-items: center; justify-content: center;
  padding: calc(16px + var(--safe-t)) 16px calc(16px + var(--safe-b));
  background: rgba(7, 5, 17, .62);
  backdrop-filter: blur(9px) saturate(.9);
  -webkit-backdrop-filter: blur(9px) saturate(.9);
  z-index: 8;
}
.modal {
  position: relative;
  width: min(440px, 100%);
  background: linear-gradient(155deg, rgba(41, 32, 76, .98), rgba(19, 14, 40, .99));
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 28px;
  box-shadow: 0 30px 80px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.14);
  padding: 26px;
  animation: popIn .32s cubic-bezier(.2,.9,.3,1);
  max-height: 92dvh;
  overflow-y: auto;
}
.modal h2 { margin: 4px 0 0; font-size: 2rem; line-height: .95; letter-spacing: -.02em; }
.modal-copy { color: var(--muted); font-size: .82rem; line-height: 1.5; margin: 12px 0 4px; }
.modal-buttons { display: flex; flex-direction: column; gap: 9px; margin-top: 20px; }
.btn-row { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.modal-note { color: var(--muted-2); font-size: .64rem; line-height: 1.5; margin: 14px 0 0; }
.pause-card { text-align: center; }
.pause-card .eyebrow { justify-content: center; }
.pause-time { margin: 18px 0 8px; display: flex; flex-direction: column; gap: 2px; }
.pause-time span { font-family: 'Baloo 2', sans-serif; font-size: 2.5rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.pause-time small { color: var(--muted-2); font-size: .66rem; letter-spacing: .12em; text-transform: uppercase; }
.pause-card .modal-buttons { max-width: 300px; margin: 20px auto 0; }
.quick-toggles { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; margin-top: 18px; }
.chip-toggle {
  display: inline-flex; align-items: center; gap: 6px;
  border: 1px solid rgba(255,255,255,.13); background: rgba(255,255,255,.055);
  color: var(--muted); border-radius: 999px; padding: 7px 11px; font-size: .66rem; font-weight: 700;
}
.chip-toggle.is-on { color: var(--cream); border-color: rgba(76,230,216,.35); background: rgba(76,230,216,.08); }
.toggle-dot { width: 7px; height: 7px; border-radius: 50%; background: rgba(255,255,255,.2); }
.chip-toggle.is-on .toggle-dot { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }

/* ---------------- Result ---------------- */

.result-screen { align-items: center; }
.result-card {
  position: relative;
  width: min(480px, 100%);
  background: linear-gradient(155deg, rgba(43, 33, 79, .98), rgba(17, 13, 36, .99));
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 30px; padding: 22px;
  box-shadow: 0 35px 90px rgba(0,0,0,.58), inset 0 1px 0 rgba(255,255,255,.15);
  animation: popIn .4s cubic-bezier(.2,.9,.3,1);
  max-height: 94dvh; overflow-y: auto;
}
.result-top { display: flex; align-items: center; gap: 16px; }
.result-copy { flex: 1; min-width: 0; }
.result-card h2 { margin: 2px 0 0; font-size: 1.85rem; line-height: .96; letter-spacing: -.02em; }
.medal {
  width: 88px; height: 88px; flex: none; border-radius: 50%;
  position: relative; display: grid; place-items: center;
  background: radial-gradient(circle at 35% 28%, #fff6c4, #ffd23f 38%, #e49613 78%);
  border: 3px solid rgba(255,255,255,.55);
  box-shadow: 0 8px 0 #a96609, 0 14px 30px rgba(255, 190, 50, .25), inset 0 2px 6px rgba(255,255,255,.5);
  transform: rotate(-5deg);
}
.medal .medal-label { font-family: 'Baloo 2', sans-serif; font-weight: 800; font-size: 1rem; color: #7b4700; letter-spacing: .04em; z-index: 2; text-shadow: 0 1px 0 rgba(255,255,255,.4); }
.medal-shine { position: absolute; inset: 8px; border-radius: 50%; border: 1px dashed rgba(120,70,0,.3); }
.medal.silver { background: radial-gradient(circle at 35% 28%, #fff, #dce5f2 40%, #94a5bc 80%); box-shadow: 0 8px 0 #637187, 0 14px 30px rgba(220,230,255,.18), inset 0 2px 6px rgba(255,255,255,.7); }
.medal.silver .medal-label { color: #405068; }
.medal.bronze { background: radial-gradient(circle at 35% 28%, #ffe2c8, #d9975c 42%, #92542a 82%); box-shadow: 0 8px 0 #683b1c, 0 14px 30px rgba(230,160,100,.18), inset 0 2px 6px rgba(255,255,255,.45); }
.medal.bronze .medal-label { color: #4c280f; }
.medal.finisher { background: radial-gradient(circle at 35% 28%, #c8c4dd, #8b86a6 45%, #56516e 85%); box-shadow: 0 8px 0 #3e3952, 0 14px 30px rgba(180,175,200,.15), inset 0 2px 6px rgba(255,255,255,.35); transform: rotate(0); }
.medal.finisher .medal-label { color: #ebe6ff; font-size: .72rem; }
.result-time {
  font-size: 2.85rem; line-height: 1; font-weight: 800; letter-spacing: -.02em;
  font-variant-numeric: tabular-nums; margin-top: 10px;
  background: linear-gradient(100deg, #fff, #ffe3ae 55%, #ffb64a);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.result-deltas { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; font-size: .68rem; font-weight: 700; color: var(--muted); }
.result-deltas .pill { border: 1px solid rgba(255,255,255,.13); background: rgba(255,255,255,.06); border-radius: 999px; padding: 4px 9px; }
.result-deltas .pill.good { color: var(--green); border-color: rgba(100,230,164,.3); background: rgba(100,230,164,.08); }
.result-deltas .pill.bad { color: #ff9c9c; }
.board { margin-top: 16px; border-top: 1px solid rgba(255,255,255,.1); padding-top: 10px; }
.board-title { display: flex; align-items: center; justify-content: space-between; font-size: .58rem; letter-spacing: .16em; font-weight: 800; color: var(--muted-2); margin-bottom: 6px; }
.board-row {
  display: grid; grid-template-columns: 24px 1fr auto; gap: 8px; align-items: center;
  padding: 7px 8px; border-radius: 10px; font-size: .76rem; color: var(--muted);
}
.board-row:nth-child(odd) { background: rgba(255,255,255,.028); }
.board-row .rank { font-family: 'Baloo 2', sans-serif; color: var(--muted-2); font-weight: 700; }
.board-row .name { color: var(--cream); font-weight: 600; display: flex; align-items: center; gap: 6px; }
.board-row .time { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--muted); }
.board-row.you { background: rgba(255,106,61,.14); border: 1px solid rgba(255,106,61,.25); }
.board-row.you .name, .board-row.you .time { color: #ffd4b8; }
.board-row.you .rank { color: var(--orange); }
.avatar { width: 18px; height: 18px; border-radius: 50%; display: inline-grid; place-items: center; font-size: .5rem; font-weight: 800; color: #171126; flex: none; }
.result-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 18px; }
.result-actions .text-btn { grid-column: 1 / -1; }
.result-share { text-align: center; margin-top: 4px; }
.confetti { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 2; }
.confetti i {
  position: absolute; top: -20px; left: var(--x); width: var(--w); height: var(--h);
  background: var(--c); border-radius: 2px; opacity: .95;
  animation: confettiFall var(--dur) var(--delay) cubic-bezier(.2,.6,.4,1) forwards;
}

/* ---------------- Builder ---------------- */

.builder-ui {
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(7, 5, 17, .8) 0%, rgba(7,5,17,.1) 18%, rgba(7,5,17,0) 68%, rgba(7,5,17,.92) 100%);
}
.builder-top {
  pointer-events: auto;
  position: absolute; top: calc(12px + var(--safe-t)); left: calc(12px + var(--safe-l)); right: calc(12px + var(--safe-r));
  display: flex; align-items: center; gap: 10px;
  padding: 9px 11px;
  background: rgba(16, 12, 34, .82);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 20px;
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
  box-shadow: 0 12px 30px rgba(0,0,0,.28);
}
.builder-heading { min-width: 0; flex: 1; }
.builder-heading .eyebrow { font-size: .5rem; letter-spacing: .16em; color: var(--muted-2); }
.builder-title-row { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.builder-title-row h2 { margin: 0; font-size: 1.06rem; line-height: 1.1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-btn { font-size: .55rem; font-weight: 800; letter-spacing: .06em; color: var(--cyan); border-color: rgba(76,230,216,.25); background: rgba(76,230,216,.08); width: auto; padding: 3px 7px; height: 22px; border-radius: 7px; }
.builder-actions { display: flex; align-items: center; gap: 6px; }
.builder-actions .icon-btn { width: 36px; height: 36px; }
.builder-hint {
  position: absolute; top: calc(82px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  font-size: .63rem; color: var(--muted); background: rgba(10,7,23,.55);
  border: 1px solid rgba(255,255,255,.1); padding: 6px 12px; border-radius: 999px;
  backdrop-filter: blur(8px); white-space: nowrap; pointer-events: none;
}
.builder-level {
  position: absolute; right: calc(14px + var(--safe-r)); top: 46%;
  transform: translateY(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  background: rgba(16,12,34,.8); border: 1px solid rgba(255,255,255,.13);
  border-radius: 16px; padding: 7px; pointer-events: auto;
  backdrop-filter: blur(14px); box-shadow: 0 10px 24px rgba(0,0,0,.25);
}
.level-btn {
  width: 34px; height: 30px; border-radius: 9px; border: 1px solid rgba(255,255,255,.14);
  background: rgba(255,255,255,.06); color: var(--cream); font-size: 1.1rem; font-weight: 600;
  display: grid; place-items: center; line-height: 1;
}
.level-btn:active { background: rgba(255,255,255,.15); }
.level-read { text-align: center; padding: 2px 0; }
.level-read span { display: block; font-size: .43rem; letter-spacing: .14em; color: var(--muted-2); font-weight: 800; }
.level-read b { font-family: 'Baloo 2', sans-serif; font-size: 1.15rem; line-height: 1; }
.builder-meta {
  position: absolute; left: calc(18px + var(--safe-l)); bottom: calc(118px + var(--safe-b));
  font-size: .58rem; letter-spacing: .08em; color: rgba(255,255,255,.38); font-weight: 700;
  pointer-events: none; text-shadow: 0 2px 10px rgba(0,0,0,.5);
}
.builder-bottom {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-end; gap: 8px;
  padding: 12px calc(10px + var(--safe-r)) calc(10px + var(--safe-b)) calc(10px + var(--safe-l));
  pointer-events: auto;
  background: linear-gradient(0deg, rgba(8,5,19,.9), rgba(8,5,19,.5) 60%, transparent);
}
.builder-toolbar { flex: none; }
.tool-btn {
  width: 58px; height: 70px; border-radius: 16px; border: 1px solid rgba(255,255,255,.13);
  background: rgba(255,255,255,.055); color: var(--muted); display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 5px; font-size: .47rem; font-weight: 800;
  letter-spacing: .08em; transition: background .15s, color .15s;
}
.tool-btn svg { width: 21px; height: 21px; }
.tool-btn:hover { background: rgba(255,255,255,.11); color: var(--cream); }
.tool-btn.rotate { width: 58px; height: 58px; border-radius: 50%; margin-bottom: 4px; }
.tool-btn.rotate span { display: none; }
.palette {
  flex: 1; display: flex; gap: 6px; overflow-x: auto; overflow-y: hidden;
  padding: 2px 2px 4px; scrollbar-width: none; -webkit-overflow-scrolling: touch;
}
.palette::-webkit-scrollbar { display: none; }
.piece-btn {
  flex: 0 0 62px; height: 70px; border-radius: 15px;
  border: 1px solid rgba(255,255,255,.11); background: rgba(255,255,255,.045);
  color: var(--muted); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px;
  font-size: .46rem; font-weight: 800; letter-spacing: .05em; text-transform: uppercase;
  transition: background .15s, border-color .15s, color .15s, transform .12s;
}
.piece-btn svg { width: 22px; height: 22px; }
.piece-btn:hover { background: rgba(255,255,255,.1); color: var(--cream); }
.piece-btn.is-active {
  background: linear-gradient(180deg, rgba(255,123,73,.95), rgba(242,72,36,.95));
  color: #fff; border-color: rgba(255,255,255,.35);
  box-shadow: 0 5px 0 rgba(150,38,16,.85), 0 8px 18px rgba(255,90,50,.25);
  transform: translateY(-2px);
}
.piece-btn.erase.is-active { background: linear-gradient(180deg, #ff6673, #d62f43); box-shadow: 0 5px 0 #90202c, 0 8px 18px rgba(255,70,90,.25); }

/* ---------------- Modal layer ---------------- */

.modal-layer {
  position: fixed; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center;
  padding: calc(16px + var(--safe-t)) 16px calc(16px + var(--safe-b));
