function handleBuilderCanvas(worldX, worldY) {
  const cell = game.updateBuilderHover(worldX, worldY);
  if (!cell) return;
  const res = game.applyBuilderAction(cell);
  if (!res.ok) {
    if (res.error) showToast(res.error);
    return;
  }
  builderState.dirty = true;
  syncBuilderUI();
  audio.click();
}

