155: function difficultyFor(pieces) {
156:   const count = (t) => pieces.filter((p) => p.t === t).length;
157:   const score = count('spinner') * 3 + count('mover') * 2.5 + count('bounce') * 1.5
158:     + count('beam') * 1.5 + count('ramp') * 1.1 + count('boost') * 1.2 + pieces.length * 0.06;
159:   if (score > 15) return 3;
160:   if (score > 7) return 2;
161:   return 1;
162: }
