402:   boxGeo(w, h, d, r = 0.09, seg = 2) {
403:     const key = `${w.toFixed(2)}|${h.toFixed(2)}|${d.toFixed(2)}|${r}|${seg}`;
404:     if (this.geometries.has(key)) return this.geometries.get(key);
405:     const safeR = Math.max(0.001, Math.min(r, Math.min(w, h, d) * 0.45));
406:     const geo = new RoundedBoxGeometry(w, h, d, seg, safeR);
407:     this.geometries.set(key, geo);
408:     return geo;
409:   }
