  await page.locator('#btn-pause').click({ force: true });
  report.pause = { visible: await page.locator('#screen-pause').isVisible(), state: await page.evaluate(() => window.MarbleRush.game.raceState), resumeVisible: await page.locator('#btn-resume').isVisible() };
  await page.locator('#btn-resume').click();
  report.resume = { hidden: await page.locator('#screen-pause').evaluate(e => e.classList.contains('is-hidden')), state: await page.evaluate(() => window.MarbleRush.game.raceState) };
