  await page.evaluate(() => window.MarbleRush.game.debugFinish());
  await page.waitForSelector('#screen-result:not(.is-hidden)');
  report.result = { visible: true, medal: await page.locator('#medal-label').textContent(), title: await page.locator('#result-title').textContent().catch(() => 'n/a') };
  await page.locator('#btn-result-exit').click();
  await page.waitForSelector('#screen-maps:not(.is-hidden)');
  await page.locator('#btn-maps-back').click();
  await page.locator('#btn-build').click();
  await page.waitForSelector('#screen-builder:not(.is-hidden)');
  report.builder = { paletteTools: await page.locator('.piece-btn').count(), meta: await page.locator('#builder-meta').innerText(), testEnabled: await page.locator('#btn-builder-test').isEnabled() };
  await page.locator('#btn-builder-test').click();
  await page.waitForFunction(() => window.MarbleRush.game.mode === 'race');
  await page.evaluate(() => window.MarbleRush.game.debugGo());
  await page.evaluate(() => window.MarbleRush.game.debugFinish());
  await page.waitForSelector('#screen-result:not(.is-hidden)');
  await page.locator('#btn-result-next').click();
  await page.waitForSelector('#screen-builder:not(.is-hidden)');
  report.builderTestReturn = await page.evaluate(() => window.MarbleRush.game.mode);
  await page.locator('#btn-builder-save').click();
  report.saveModal = await page.locator('#modal-save').isVisible();
  await page.locator('#save-name').fill('Mobile Flow Course');
  await page.locator('#btn-save-confirm').click();
  await page.waitForTimeout(100);
  report.saved = { name: await page.locator('#builder-name').textContent(), storedMaps: await page.evaluate(() => window.MarbleRush.store.customMaps().length) };
  const layout = await page.evaluate(() => ({ viewport: [innerWidth, innerHeight], document: [document.documentElement.scrollWidth, document.documentElement.scrollHeight], canvas: [document.querySelector('#scene').width, document.querySelector('#scene').height] }));
  report.layout = layout;
